  ((select id from public.projects where slug = 'robotic-arm-cad-simulation-control'), $p$projects/robotic-arm/assembly-side.png$p$, $p$Side view of the assembled robotic arm$p$, 1),
  ((select id from public.projects where slug = 'robotic-arm-cad-simulation-control'), $p$projects/robotic-arm/parts-sheet.png$p$, $p$The individual SolidWorks parts of the arm$p$, 2),
  ((select id from public.projects where slug = 'robotic-arm-cad-simulation-control'), $p$projects/robotic-arm/tutorial-2dof.png$p$, $p$The simpler 2-DOF tutorial arm$p$, 3),
  ((select id from public.projects where slug = 'robotic-arm-cad-simulation-control'), $p$projects/robotic-arm/workflow.png$p$, $p$Workflow from SolidWorks CAD through Simscape, inverse kinematics and PID control$p$, 4);

